#!/usr/bin/env bash
set -euo pipefail
# count-errors.sh FILE : how many lines mention ERROR
[ $# -eq 1 ] || { echo "usage: count-errors.sh FILE" >&2; exit 2; }
file=$1
[ -r "$file" ] || { echo "error: cannot read $file" >&2; exit 2; }
n=$(grep -c ERROR -- "$file" || true)
echo "errors: $n"

