solution.report.sh:
#!/usr/bin/env bash
set -euo pipefail
# report.sh FILE... : "FILE: N bytes" for each file; stop at the first one that cannot be read
[ $# -gt 0 ] || { echo "usage: report.sh FILE..." >&2; exit 2; }
report() {
  local size
  size=$(stat -c %s -- "$1")
  echo "$1: $size bytes"
}
for f in "$@"; do
  report "$f"
done

