#!/usr/bin/env bash
set -euo pipefail
# listing.sh DIR : print the sorted names of the entries of DIR, using a scratch directory
trap 'rm -rf "$tmp"' EXIT
usage() { echo "usage: listing.sh DIR" >&2; exit 2; }
[ $# -eq 1 ] || usage
[ -d "$1" ] || { echo "error: not a directory: $1" >&2; exit 2; }
tmp=$(mktemp -d)
ls -A -- "$1" > "$tmp/names"
LC_ALL=C sort "$tmp/names"

